class IsoCube {
	constructor(x, y, s = 10, h = 10, l) {
		const sx = (x - y) * s * Math.sqrt(3) * 0.5;
		const sy = s / 2 +  x * s * 0.5 +  y * s * 0.5;
		this.x = sx; // pos x
		this.y = sy; // pos y
		this.s = s; // size
		this.h = h; // hue color
		this.l = l || s; // length
	}

	// https://en.wikipedia.org/wiki/Isometric_projection
	show() {
		push()
		rectMode(CENTER)
		colorMode(HSB)

		translate(this.x, this.y)

		const x = this.s * Math.sqrt(3) * 0.5;
		const y = this.s * 0.5;

		// console.log("" + x + ", " + y + ", " + this.l)

		// base
		fill(this.h, 50, 50)
		if (this.l <= 0) fill((this.x + this.y) % 8 + 16)
		quad(x, 0, 0, y, -x, 0, 0, -y)
		if (this.l > 0) {
			/* lines
			push()
			const d = 16
			strokeWeight(d)
			stroke(0)
			line(-x + d, -this.l, 0, -y - this.l + d * 0.5)
			stroke(128)
			line(x - d, -this.l, 0, -y - this.l + d * 0.5)
			pop()
			*/
			// left
			fill(this.h, 65, 75)
			quad(0, y, -x, 0, -x, -this.l, 0, y - this.l)
			// right
			fill(this.h, 85, 25)
			quad(0, y, x, 0, x, -this.l, 0, y - this.l)
			// top
			fill(this.h, 75, 60)
			quad(x, -this.l, 0, y - this.l, -x, -this.l, 0, -y - this.l)
		}
		pop()
	}

}
